independent_result_readback.cmd:
env -u PYTHONPATH -u PYTHONHOME -u PYTHONUSERBASE -u LD_PRELOAD -u LD_LIBRARY_PATH -u LD_AUDIT PYTHONNOUSERSITE=1 PYTHONDONTWRITEBYTECODE=1 PYTHONHASHSEED=0 OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 benchmarks/work/native_factorial_review_py310_20261004/bin/python -I -B -c 'import csv,hashlib,itertools,json,math,pathlib,sys
from fractions import Fraction
from Bio import SeqIO
import numpy as np
sys.path.insert(0,str(pathlib.Path.cwd()))
from benchmark_tools.orthofinder_mcl_to_orthogroups import iter_mcl_clusters,load_sequence_ids
root=pathlib.Path.cwd()
directory=root/"benchmark_tools/results/controlled_fragment_results_20261009_v1"
raw=(directory/"report.json").read_bytes()
assert hashlib.sha256(raw).hexdigest()=="b1480e8eb2ace2aed743f5fc4e515e27ac4ba68b48e644b33989eda3cf8a7ab7"
report=json.loads(raw)
panel=json.loads(pathlib.Path(report["manifest"]["absolute_path"]).read_text())
parent=json.loads((root/"benchmark_tools/results/publication_variable_native_methods_20260916.json").read_text())
old={d["seed"]:d for d in parent["datasets"] if d["condition"]=="baseline"}
methods=("orthohmm_high_sensitivity","orthohmm_satellite_v2","orthofinder_full","orthofinder_sequence_only")
def verify(item):
    p=pathlib.Path(item["absolute_path"])
    assert p.stat().st_size==item["bytes"] and hashlib.sha256(p.read_bytes()).hexdigest()==item["sha256"]
def group_pairs(groups,owners):
    seen=set()
    pairs=set()
    for group in groups:
        assert group and all(g in owners and g not in seen for g in group) and len(set(group))==len(group)
        seen.update(group)
        pairs.update(tuple(sorted((a,b))) for a,b in itertools.combinations(group,2) if owners[a]!=owners[b])
    return pairs
def predictions(method,config,owners,artifacts):
    for item in artifacts: verify(item)
    if method==methods[0]:
        groups=[]
        for line in pathlib.Path(artifacts[0]["absolute_path"]).read_text().splitlines():
            tokens=line.split()
            assert tokens and tokens[0].endswith(":")
            groups.append(tokens[1:])
        return group_pairs(groups,owners)
    if method==methods[1]:
        with pathlib.Path(artifacts[0]["absolute_path"]).open() as f:
            rows=list(csv.DictReader(f,delimiter="\t"))
        result=set()
        for row in rows:
            a,b=row["gene_a"],row["gene_b"]
            assert owners[a]==row["species_a"] and owners[b]==row["species_b"] and owners[a]!=owners[b]
            result.add(tuple(sorted((a,b))))
        return result
    if method==methods[2]:
        orientations={}
        for item in artifacts:
            with pathlib.Path(item["absolute_path"]).open() as f:
                reader=csv.reader(f,delimiter="\t")
                header=next(reader)
                assert len(header)==3 and header[0]=="Orthogroup"
                a,b=header[1:]
                assert (a,b) not in orientations
                pairs=set()
                for row in reader:
                    left=[x.strip() for x in row[1].split(",")]
                    right=[x.strip() for x in row[2].split(",")]
                    assert all(owners[g]==a for g in left) and all(owners[g]==b for g in right)
                    pairs.update(tuple(sorted(p)) for p in itertools.product(left,right))
                orientations[a,b]=pairs
        species=set(owners.values())
        assert set(orientations)==set(itertools.permutations(species,2))
        assert all(pairs==orientations[b,a] for (a,b),pairs in orientations.items())
        return set.union(*orientations.values())
    mapping_path=next(pathlib.Path(i["absolute_path"]) for i in artifacts if pathlib.Path(i["absolute_path"]).name=="SequenceIDs.txt")
    matrix=next(pathlib.Path(i["absolute_path"]) for i in artifacts if "id_pairs" in pathlib.Path(i["absolute_path"]).name)
    mapping=load_sequence_ids(mapping_path)
    assert set(mapping.values())==set(owners) and len(mapping)==len(owners)
    return group_pairs([[mapping[g] for g in cluster] for cluster in iter_mcl_clusters(matrix)],owners)
def counts(p,t,owners):
    assert all(a in owners and b in owners and a!=b and owners[a]!=owners[b] for a,b in p|t)
    tp=len(p&t); fp=len(p-t); fn=len(t-p)
    covered={g for pair in p for g in pair}
    return dict(tp=tp,fp=fp,fn=fn,predicted_pairs=len(p),eligible_true_pairs=len(t),
        f1=float(Fraction(2*tp,2*tp+fp+fn)) if 2*tp+fp+fn else None,
        precision=float(Fraction(tp,len(p))) if p else None,recall=float(Fraction(tp,len(t))) if t else None,
        input_genes=len(owners),genes_in_predicted_pairs=len(covered),pair_endpoint_coverage=float(Fraction(len(covered),len(owners))))
indexed={(r["arm"],r["seed"],r["method"]):r for r in report["records"]}
assert len(indexed)==80 and all(r["status"]=="complete" for r in indexed.values())
recomputed={}
for d in panel["datasets"]:
    verify(d["coordinates"])
    flags={r["gene"]:r["fragment"] for r in json.loads(pathlib.Path(d["coordinates"]["absolute_path"]).read_text())}
    owners={s.id:p.stem for p in pathlib.Path(d["input"]).glob("*.fasta") for s in SeqIO.parse(p,"fasta")}
    t={tuple(sorted(p)) for p in json.loads(pathlib.Path(d["truth"]).read_text())["ortholog_pairs"]}
    for arm in ("baseline","fragment"):
        config=old[d["seed"]] if arm=="baseline" else d
        binding={r["method"]:r for r in d["baseline_admission"]}
        for m in methods:
            r=indexed[arm,d["seed"],m]
            artifacts=binding[m]["predictions"] if arm=="baseline" else r["prediction_artifacts"]
            p=predictions(m,config["methods"][m],owners,artifacts)
            c=counts(p,t,owners)
            assert all(r["score"][k]==v for k,v in c.items())
            for stratum in r["strata"]:
                n=stratum["fragment_endpoints"]
                pc={pair for pair in p if sum(flags[g] for g in pair)==n}
                tc={pair for pair in t if sum(flags[g] for g in pair)==n}
                cs=counts(pc,tc,owners)
                assert all(stratum["score"][k]==v for k,v in cs.items())
            recomputed[arm,d["seed"],m]=c
for r in report["metric_means"]:
    for metric in ("f1","precision","recall"):
        values=[recomputed[r["arm"],seed,r["method"]][metric] for seed in range(20261101,20261111)]
        assert abs(sum(values)/10-r["metrics"][metric]["mean"])<1e-15
planned=[("fragment",m,"baseline",m) for m in methods[:3]]+[("fragment",m,"fragment",methods[2]) for m in methods[:2]]
assert [(r["target_arm"],r["target_method"],r["reference_arm"],r["reference_method"],r["metric"]) for r in report["comparisons"]]==[(*p,m) for p in planned for m in ("f1","precision","recall")]
for r in report["comparisons"]:
    assert r["eligible_seeds"]==list(range(20261101,20261111)) and r["excluded_seeds"]==[]
    values=np.array([recomputed[r["target_arm"],s,r["target_method"]][r["metric"]]-recomputed[r["reference_arm"],s,r["reference_method"]][r["metric"]] for s in r["eligible_seeds"]])
    assert np.max(np.abs(values-np.array(r["paired_differences"])))<1e-15 and abs(float(values.mean())-r["estimate"])<1e-15
    rng=np.random.Generator(np.random.PCG64(20261011))
    draws=rng.integers(0,10,(20000,10))
    distribution=np.sort(values[draws].mean(axis=1))
    for name,probs in (("nominal_interval",(.025,.975)),("adjusted_interval",(.05/30,1-.05/30))):
        expected=[]
        for prob in probs:
            location=(len(distribution)-1)*prob
            left=math.floor(location); right=math.ceil(location)
            expected.append(float(distribution[left]+(distribution[right]-distribution[left])*(location-left)))
        assert max(abs(a-b) for a,b in zip(expected,r[name]))<1e-15
for filename,stratified in (("scores.tsv",False),("strata.tsv",True)):
    with (directory/filename).open() as f: rows=list(csv.DictReader(f,delimiter="\t"))
    assert len(rows)==(240 if stratified else 80)
    for row in rows:
        source=indexed[row["arm"],int(row["seed"]),row["method"]]
        score=source["strata"][int(row["fragment_endpoints"])]["score"] if stratified else source["score"]
        for key in ("tp","fp","fn","f1","precision","recall","predicted_pairs","eligible_true_pairs","pair_endpoint_coverage"):
            assert (row[key]=="NA" and score[key] is None) or (score[key] is not None and abs(float(row[key])-score[key])<1e-15)
with (directory/"comparisons.tsv").open() as f: rows=list(csv.DictReader(f,delimiter="\t"))
assert len(rows)==15
for row,source in zip(rows,report["comparisons"]):
    assert float(row["estimate"])==source["estimate"] and int(row["paired_seeds"])==10
    for prefix in ("nominal","adjusted"):
        assert float(row[prefix+"_low"])==source[prefix+"_interval"][0] and float(row[prefix+"_high"])==source[prefix+"_interval"][1]
print(json.dumps(dict(status="independent_counts_intervals_and_tables_verified",score_records=80,stratum_records=240,planned_comparisons=15,bootstrap_replicates=20000,reader_scope="Independent native pair/group expansion and Fraction counts; shared audited MCL syntax parser only; independent sorted linear interval interpolation",report_sha256=hashlib.sha256(raw).hexdigest()),sort_keys=True))'
